// Des: Command-line parsing for scra
// Flo: walk argv > flags with values > switches > first word = command, second = URL > typed BadUsage on anything unknown
// I/O: argv strings (caller) > Args struct (slices into argv)
// ===================================================================
const std = @import("std");
pub const Args = struct { cmdz: []const u8 = "", urlz: []const u8 = "", json: bool = false, live: bool = false, forc: bool = false, onzz: bool = false, offz: bool = false, conf: []const u8 = "", fmtz: []const u8 = "jsonl", outz: []const u8 = "", seed: []const u8 = "", smap: []const u8 = "", adds: []const u8 = "", decl: u32 = 0, helz: bool = false };
fn valu(iter: anytype) ![]const u8 { return iter.next() orelse return error.BadUsage; }
pub fn argsRead(argv: []const []const u8) !Args { var args: Args = .{}; var indx: usize = 0; while (indx < argv.len) : (indx += 1) { const item = argv[indx]; if (std.mem.eql(u8, item, "--json")) { args.json = true; } else if (std.mem.eql(u8, item, "--live")) { args.live = true; } else if (std.mem.eql(u8, item, "--force")) { args.forc = true; } else if (std.mem.eql(u8, item, "--on")) { args.onzz = true; } else if (std.mem.eql(u8, item, "--off")) { args.offz = true; } else if (std.mem.eql(u8, item, "--help") or std.mem.eql(u8, item, "-h")) { args.helz = true; } else if (std.mem.eql(u8, item, "--conf") or std.mem.eql(u8, item, "--format") or std.mem.eql(u8, item, "--out") or std.mem.eql(u8, item, "--seed-file") or std.mem.eql(u8, item, "--sitemap") or std.mem.eql(u8, item, "--add") or std.mem.eql(u8, item, "--decl")) { indx += 1; if (indx >= argv.len) return error.BadUsage; const val = argv[indx]; if (std.mem.eql(u8, item, "--conf")) args.conf = val else if (std.mem.eql(u8, item, "--format")) args.fmtz = val else if (std.mem.eql(u8, item, "--out")) args.outz = val else if (std.mem.eql(u8, item, "--seed-file")) args.seed = val else if (std.mem.eql(u8, item, "--sitemap")) args.smap = val else if (std.mem.eql(u8, item, "--add")) args.adds = val else args.decl = std.fmt.parseInt(u32, val, 10) catch return error.BadUsage; } else if (item.len > 0 and item[0] == '-') { return error.BadUsage; } else if (args.cmdz.len == 0) { args.cmdz = item; } else if (args.urlz.len == 0) { args.urlz = item; } else { return error.BadUsage; } } if (args.onzz and args.offz) return error.BadUsage; if (args.forc and !args.live) return error.BadUsage; return args; }
